import { useState, useCallback, useEffect } from "react";
import Box from "@mui/material/Box";
import ButtonBase from "@mui/material/ButtonBase";
import IconButton from "@mui/material/IconButton";
import Popover from "@mui/material/Popover";
import Tooltip from "@mui/material/Tooltip";
import CloseIcon from "@mui/icons-material/Close";
import RefreshIcon from "@mui/icons-material/Refresh";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";

import type { SlotInsight } from "../types/insightSlots";
import { useInsightStatusStore } from "../store/useInsightStatusStore";

import { useSlotInsight, useInsightSlotContext } from "./InsightSlotHooks";
import { severityGlow, severityColor, pulseSx, popoverMarkdownSx } from "./insightSlotSx";

export interface InsightSlotProps {
  /** Slot identifier that maps to a `SlotInsight` in the context. */
  slotId: string;
  /** The component(s) this slot decorates. */
  children: React.ReactNode;
  /** Optional action buttons (e.g. "Group by host.name") rendered before refresh/dismiss. */
  renderActions?: (insight: SlotInsight) => React.ReactNode;
}

/**
 * Wraps a component with slot-attached insight affordances.
 *
 * When an insight exists for the given `slotId` the wrapper renders:
 * - A subtle severity glow around the children.
 * - A small pulsing indicator dot (keyboard-focusable).
 * - A popover (on click / Enter / Space) showing the insight text as markdown
 *   with refresh and dismiss actions.
 *
 * When no insight is present, or the slot has been dismissed, children are
 * rendered unchanged.
 *
 * Each active insight wrapper is tagged with `data-insight-slot-id` so the
 * footer navigation can scroll to the next undismissed insight.
 */
export default function InsightSlot({ slotId, children, renderActions }: InsightSlotProps) {
  const insight = useSlotInsight(slotId);
  const { loading, refresh } = useInsightSlotContext();
  const dismissSlot = useInsightStatusStore((s) => s.dismissSlot);

  const dismissKey = `insight-slot-dismissed:${slotId}`;
  const [dismissedSlotId, setDismissedSlotId] = useState<string | null>(null);
  const [anchor, setAnchor] = useState<{ slotId: string; el: HTMLElement } | null>(null);

  const anchorEl = anchor?.slotId === slotId ? anchor.el : null;
  const open = Boolean(anchorEl);
  const dismissedInSession =
    typeof window !== "undefined" && window.sessionStorage.getItem(dismissKey) === "1";

  // Rehydrate persisted dismissals into the global store so the footer
  // badge and jump control stay in sync after a page remount.
  useEffect(() => {
    if (dismissedInSession && insight) {
      dismissSlot(slotId);
    }
  }, [dismissedInSession, insight, slotId, dismissSlot]);

  const handleOpen = useCallback(
    (event: React.SyntheticEvent<HTMLElement>) => {
      setAnchor({ slotId, el: event.currentTarget });
    },
    [slotId],
  );

  const handleClose = useCallback(() => {
    setAnchor(null);
  }, []);

  const handleDismiss = useCallback(() => {
    setAnchor(null);
    setDismissedSlotId(slotId);
    dismissSlot(slotId);
    if (typeof window !== "undefined") {
      window.sessionStorage.setItem(dismissKey, "1");
    }
  }, [dismissKey, slotId, dismissSlot]);

  const handleRefresh = useCallback(() => {
    setAnchor(null);
    refresh();
  }, [refresh]);

  // No insight or loading — render children unchanged.
  if (!insight || loading) {
    return <>{children}</>;
  }

  // Dismissed — render children without decoration.
  if (dismissedSlotId === slotId || dismissedInSession) {
    return <>{children}</>;
  }

  const severity = insight.severity ?? "info";
  const actions = renderActions?.(insight);

  return (
    <Box
      data-insight-slot-id={slotId}
      sx={{
        position: "relative",
        display: "block",
        width: "100%",
        minWidth: 0,
        maxWidth: "100%",
        boxShadow: severityGlow(severity),
        borderRadius: 1,
        transition: "box-shadow 0.3s ease",
      }}
    >
      {children}

      {/* Pulse indicator dot */}
      <ButtonBase
        aria-label={`View ${severity} insight`}
        aria-haspopup="true"
        aria-expanded={open}
        onClick={handleOpen}
        sx={{
          position: "absolute",
          top: -11,
          right: -11,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          width: 24,
          minWidth: 24,
          height: 24,
          p: 0,
          borderRadius: "50%",
          "&:focus-visible": {
            outline: "2px solid",
            outlineColor: "primary.main",
            outlineOffset: 2,
          },
        }}
      >
        <Box
          component="span"
          sx={[
            {
              width: 10,
              height: 10,
              borderRadius: "50%",
              bgcolor: severityColor(severity),
            },
            pulseSx,
          ]}
        />
      </ButtonBase>

      {/* Insight popover */}
      <Popover
        open={open}
        anchorEl={anchorEl}
        onClose={handleClose}
        anchorOrigin={{ vertical: "bottom", horizontal: "right" }}
        transformOrigin={{ vertical: "top", horizontal: "right" }}
        slotProps={{ paper: { sx: { maxWidth: 360, p: 2 } } }}
      >
        <Box sx={popoverMarkdownSx}>
          <ReactMarkdown remarkPlugins={[remarkGfm]}>{insight.text}</ReactMarkdown>
        </Box>

        {actions && <Box sx={{ mt: 1 }}>{actions}</Box>}

        <Box sx={{ display: "flex", gap: 0.5, justifyContent: "flex-end", mt: 1 }}>
          <Tooltip title="Refresh insight">
            <IconButton size="small" aria-label="Refresh insight" onClick={handleRefresh}>
              <RefreshIcon fontSize="small" />
            </IconButton>
          </Tooltip>
          <Tooltip title="Dismiss insight">
            <IconButton size="small" aria-label="Dismiss insight" onClick={handleDismiss}>
              <CloseIcon fontSize="small" />
            </IconButton>
          </Tooltip>
        </Box>
      </Popover>
    </Box>
  );
}
